/**
 * A user-held delivery capability. Never place this code in a URL, email,
 * analytics, server logs, or Stripe metadata. Only a SHA-256 digest is persisted.
 * The 256-bit token is generated by crypto.randomBytes in the service.
 */
const UUID_V4=/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
const TOKEN=/^[A-Za-z0-9_-]{43}$/;

export function recoveryCode(id:string,token:string):string {
 if(!UUID_V4.test(id)||!TOKEN.test(token))throw new Error("INVALID_RECOVERY_CODE");
 return `CS1.${id}.${token}`;
}

/**
 * Recover the report ID from the user-held capability itself. This enables
 * retrieval on a different device without requiring the old success-page URL.
 * Never navigate with either the code or token in a URL.
 */
export function parseStandaloneRecoveryCode(raw:string):{id:string;token:string}|null {
 if(typeof raw!=="string"||raw.length>100)return null;
 const parts=raw.trim().split(".");
 if(parts.length!==3||parts[0]!=="CS1"||!UUID_V4.test(parts[1])||!TOKEN.test(parts[2]))return null;
 return {id:parts[1],token:parts[2]};
}

/** Accept a complete code only, bound to this exact report (no URLs or bare tokens). */
export function parseRecoveryCode(id:string,raw:string):string|null {
 const parsed=parseStandaloneRecoveryCode(raw);
 return parsed?.id===id?parsed.token:null;
}

/**
 * Select the credentials for a document download. A pasted code takes
 * precedence, and cannot silently switch an explicitly addressed report.
 * Recovered credentials can be reused on the same page after a first download.
 */
export function resolveDeliveryAccess(
 routeId:string,storedReportId:string,storedToken:string,pastedCode:string
):{id:string;token:string;manual:boolean}|null {
 if(pastedCode.trim()){
  const parsed=parseStandaloneRecoveryCode(pastedCode);
  return parsed&&(!routeId||parsed.id===routeId)?{...parsed,manual:true}:null;
 }
 const id=routeId||storedReportId;
 if(!UUID_V4.test(id)||!TOKEN.test(storedToken)||(routeId&&storedReportId&&storedReportId!==routeId))return null;
 return {id,token:storedToken,manual:false};
}
